-- Explicit duration and unit; retain valid_days only as a compatibility projection.
ALTER TABLE eam_maintenance_plan_device
  ADD COLUMN valid_duration INT NOT NULL DEFAULT 0 COMMENT '任务有效时长数量，0表示不过期',
  ADD COLUMN valid_unit VARCHAR(8) NOT NULL DEFAULT '日' COMMENT '任务有效时长单位：日、周、月';
UPDATE eam_maintenance_plan_device SET valid_duration=valid_days;
ALTER TABLE eam_maintenance_plan_device
  ADD CONSTRAINT chk_maintenance_valid_duration CHECK (valid_duration >= 0 AND valid_duration <= 36500),
  ADD CONSTRAINT chk_maintenance_valid_unit CHECK (valid_unit IN ('日','周','月'));

CREATE OR REPLACE VIEW v_maintenance_schedule AS SELECT d.*, COALESCE(d.legacy_standard_id,(SELECT r.standard_id FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id ORDER BY r.sort_no LIMIT 1),0) AS standard_id,JSON_REMOVE(JSON_OBJECT('id',CAST(d.id AS CHAR),'equipmentId',CAST(d.equipment_id AS CHAR),'typeId',CAST(d.type_id AS CHAR),'nextDate',DATE_FORMAT(d.next_date,'%Y-%m-%d'),'period',d.`period_count`,'unit',d.`period_unit`,'validDays',d.`valid_days`,'validDuration',d.valid_duration,'validUnit',d.valid_unit,'remark',d.`remark`,'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_person r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_person r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'projectRefs',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('standardId',CAST(r.standard_id AS CHAR),'itemId',r.item_key)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id LIMIT 1),JSON_ARRAY()),'standardId',CAST(COALESCE(d.legacy_standard_id,(SELECT r.standard_id FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id ORDER BY r.sort_no LIMIT 1),0) AS CHAR)),IF(d.legacy_standard_id IS NULL,'$.unusedCompatibilityKey','$.projectRefs')) AS payload FROM eam_maintenance_plan_device d;
